size_t nbits = binfo->nbits;
    size_t nwords = binfo->nwords;
    size_t *bits = bitmap->bits;

    for (size_t i = 0; i < nwords; i++) {
        size_t word = bits[i];
        if (word != std::numeric_limits<size_t>::max()) {
            size_t bit_index = i * (sizeof(size_t) * 8);
            size_t mask = 1;

            while (mask != 0 && (word & mask) != 0) {
                mask <<= 1;
                bit_index++;
            }

            if (mask != 0) {
                size_t old_word = word;
                word |= mask;
                if (std::atomic_compare_exchange_strong(
                        reinterpret_cast<std::atomic<size_t>*>(&bits[i]),
                        &old_word, word)) {
                    return bit_index;
                }
                // CAS failed, retry with updated word
                i--;
            }
        }
    }

    return nbits; // No unset bit found
// END_CODE

